+import type { Board, Pos, Verdict } from "./types";
+
+export function horseMove(board: Board, from: Pos, to: Pos): Verdict {
+  const dx = to.x - from.x;
+  const dy = to.y - from.y;
+  const ok = (Math.abs(dx) === 1 && Math.abs(dy) === 2) || (Math.abs(dx) === 2 && Math.abs(dy) === 1);
+  if (!ok) return { legal: false, reason: "马走日" };
+  // The leg is the point next to the horse in the direction of the longer step.
+  const leg = Math.abs(dx) === 2 ? { x: from.x + dx / 2, y: from.y } : { x: from.x, y: from.y + dy / 2 };
+  if (board.at(leg)) return { legal: false, reason: "蹩马腿" };
+  return { legal: true };
+}
