+import { expect, it } from "vitest";
+import { emptyBoard, place } from "./testing";
+import { horseMove } from "./horse";
+
+it("moves in an L", () => {
+  expect(horseMove(emptyBoard(), { x: 1, y: 0 }, { x: 2, y: 2 }).legal).toBe(true);
+});
+it("is blocked by a piece on its leg", () => {
+  const board = place(emptyBoard(), { x: 1, y: 1 }, "兵");
+  expect(horseMove(board, { x: 1, y: 0 }, { x: 2, y: 2 })).toEqual({ legal: false, reason: "蹩马腿" });
+});
